function isGtaViGame(gameName, title) {
  const normalizedGame = (gameName ?? "").trim();
  if (/\b(grand\s+theft\s+auto\s*(vi|6)|gta\s*(vi|6))\b/i.test(normalizedGame))
    return true;
  if (!normalizedGame && title) {
    return /\b(grand\s+theft\s+auto\s*(vi|6)|gta\s*(vi|6))\b/i.test(title);
  }
  return false;
}
function classifySpoilerRisk(title) {
  if (!title) return "unknown";
  const text = title.toLowerCase();
  if (/(sin\s+spoilers?|no\s+spoilers?|spoiler[\s-]*free|solo\s+explorando|free\s*roam|paseando|sin\s+historia)/i.test(
    text
  ))
    return "spoiler-free";
  if (/(caos|polic[ií]a|estrellas|explora|mapa|online|\brp\b|roleplay|tuning|coches)/i.test(
    text
  ))
    return "freeroam";
  if (/(historia|campa[nñ]a|misi[oó]n|final|ending|cap[ií]tulo|chapter|pr[oó]logo|jason|lucia|story|walkthrough|parte\s*\d|#\d)/i.test(
    text
  ))
    return "story";
  return "unknown";
}
function streamLookupKey(platform, handle) {
  return `${platform}:${handle.toLowerCase()}`;
}

